        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Visual acuity"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Approximately 6/9 in both eyes with spectacles; unchanged per patient."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Reported eye symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Several months of increased watery tearing, left greater than right, worse outdoors and in wind; mild gritty or sandy sensation, especially at the end of the day; occasional mild morning crusting. Clear tearing only. No significant pain, photophobia, reduced visual acuity, diplopia, flashes, floaters, curtain, trauma, foreign body, or contact lens use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Eye examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Obvious left lower eyelid ectropion with punctum not apposed; mild inferior left conjunctival injection and clear tearing; mild left lower eyelid erythema/dermatitis from wiping. No periorbital swelling, lacrimal sac tenderness, or warmth. Cornea clear on torch examination with no obvious ulcer or abrasion. Pupils equal and reactive; no relative afferent pupillary defect. Extraocular movements full and non-painful. Right eye with mild age-related changes only."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Red flag eye features"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No red flag features reported or identified today."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Over-the-counter artificial tears"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "As needed, approximately 1–2 times daily; brief relief.",
            "asNeededBoolean": true
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Preservative-free artificial tears"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Use in the left eye four times daily and as needed; may use in both eyes if dry. PBS brand as available.",
            "route": {
              "text": "ophthalmic"
            },
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-2",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-2",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Paraffin-based lubricating eye ointment (e.g. VitA/PF)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Use in the left eye at night.",
            "route": {
              "text": "ophthalmic"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d",
                "when": [
                  "HS"
                ]
              }
            }
          }
        ]
      }
    }
  ]
}
